<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue';
const props=defineProps<{cnpj:string;request:<T>(path:string)=>Promise<T>}>();
const emit=defineEmits<{apply:[data:Record<string,unknown>]}>();
type Result=Record<string,unknown>&{cnpj:string;razao_social:string;nome_fantasia:string;uf:string;municipio:string;fonte:string;consultado_em:string;situacao_cadastral:string;endereco:Record<string,string>;cnae_principal:{codigo:string;descricao:string};cnaes_secundarios:Array<{codigo:string;descricao:string}>};
const normalize=(value:string)=>value.replace(/[^a-z0-9]/gi,'').toUpperCase();
const result=ref<Result|null>(null),busy=ref(false),error=ref('');let generation=0;
watch(()=>props.cnpj,()=>{generation++;result.value=null;error.value='';busy.value=false;});
onBeforeUnmount(()=>{generation++;});
async function lookup(){const current=++generation,cnpj=normalize(props.cnpj);busy.value=true;error.value='';result.value=null;try{const data=await props.request<Result>('/api/contexto/clientes/consulta-cnpj/'+encodeURIComponent(cnpj||'invalido'));if(current!==generation)return;if(data.cnpj!==cnpj)throw new Error('A consulta retornou dados de outro CNPJ.');result.value=data;}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)busy.value=false;}}
</script>
<template><div class="cnpj-lookup"><button class="secondary" type="button" :disabled="busy" @click="lookup">{{ busy?'Consultando…':'Consultar CNPJ' }}</button><p v-if="error" role="alert">{{ error }}</p><article v-if="result"><h3>{{ result.razao_social }}</h3><p>{{ result.cnpj }} · {{ result.situacao_cadastral||'Situação não informada' }}</p><details><summary>Dados cadastrais completos</summary><p>Nome fantasia: {{ result.nome_fantasia||'Não informado' }}</p><p>Localidade: {{ result.municipio }} / {{ result.uf }}</p><p>Endereço: {{ Object.values(result.endereco||{}).filter(Boolean).join(' · ') }}</p><p>CNAE principal: {{ result.cnae_principal?.codigo }} · {{ result.cnae_principal?.descricao }}</p><p v-for="cnae in result.cnaes_secundarios" :key="cnae.codigo">CNAE secundário: {{ cnae.codigo }} · {{ cnae.descricao }}</p><p>Natureza jurídica: {{ result.natureza_juridica }}</p><p>Porte: {{ result.porte }}</p><p>Início da atividade: {{ result.inicio_atividade }}</p><p>Situação desde: {{ result.data_situacao_cadastral }}</p></details><p>Fonte: {{ result.fonte }} · {{ new Date(result.consultado_em).toLocaleString('pt-BR') }}</p><p>Confira os dados e o enquadramento. O cliente só será gravado ao salvar.</p><button type="button" class="secondary" @click="emit('apply',result)">Usar dados no cadastro</button></article></div></template>
